fn shell_game(n: i32, x: i8) -> i8 {
    // The moves repeat every 6 steps in a cycle:
    // Because odd steps swap 0<->1, even steps swap 1<->2,
    // after 6 steps, the positions repeat.

    // Compute n modulo 6 to reduce the problem to at most 6 moves
    let n_mod = (n % 6) as usize;

    // We'll simulate moves up to n_mod directly for simplicity and performance
    let mut pos = x;

    for i in 1..=n_mod {
        if i % 2 == 1 {
            // Odd step: swap 0 and 1
            pos = match pos {
                0 => 1,
                1 => 0,
                2 => 2,
                _ => pos, // Should never happen as pos in {0,1,2}
            };
        } else {
            // Even step: swap 1 and 2
            pos = match pos {
                0 => 0,
                1 => 2,
                2 => 1,
                _ => pos,
            };
        }
    }

    pos
}